// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
        c.initialize(address(new MockConfig()));
    }

    function testFuzz_property(address manager) public {
        vm.assume(manager != address(0) && manager != address(this));

        // first pause by the manager succeeds in the reference contract
        vm.prank(manager);
        c.pause();

        // rule: once paused, a further pause() by the manager must revert
        vm.prank(manager);
        bool ok;
        try c.pause() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok, "second pause must revert once the contract is paused");
    }
}

contract MockConfig {
    bytes32 public constant MANAGER = keccak256("MANAGER");

    function hasRole(bytes32 role, address account) external view returns (bool) {
        if (role == MANAGER) {
            return account != address(0);
        }
        return false;
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    MockConfig cfg;

    function setUp() public { c = new C(); }

    function testFuzz_property(address manager, address admin) public {
        vm.assume(manager != address(0) && admin != address(0) && manager != admin);
        cfg = new MockConfig();
        cfg.setRole(0x00, admin, true); // DEFAULT_ADMIN_ROLE
        cfg.setRole(keccak256("MANAGER"), manager, true);
        c.initialize(address(cfg));

        // manager pauses the contract
        vm.prank(manager);
        c.pause();

        // Rule: once paused, an admin can always successfully unpause.
        vm.prank(admin);
        bool ok;
        try c.unpause() { ok = true; } catch { ok = false; }

        assertTrue(ok, "admin unpause after pause must succeed");
    }
}

contract MockConfig {
    mapping(bytes32 => mapping(address => bool)) public roles;

    function setRole(bytes32 role, address account, bool val) external {
        roles[role][account] = val;
    }

    function hasRole(bytes32 role, address account) external view returns (bool) {
        return roles[role][account];
    }
}

