pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address configAddr) public {
        // Any nonzero address is an admissible config address for initialize;
        // we only exercise the pause-state getter afterwards.
        vm.assume(configAddr != address(0));

        c.initialize(configAddr);

        // General rule: a freshly initialized (never paused) contract reports
        // paused() == false, for every admissible input.
        // The mutant returns !_paused, i.e. true here, breaking the rule.
        assertTrue(c.paused() == false);
    }
}

