pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address newCfg, address admin) public {
        // keep the new config address in the admissible domain (non-zero, as required by UtilLib)
        vm.assume(newCfg != address(0));
        vm.assume(admin != address(0));

        // try to bring the contract to an initialized state (implementation may disallow it;
        // both variants behave identically here, so it does not affect the distinguishing rule)
        vm.prank(admin);
        try c.initialize(address(this)) {
            // initialized
        } catch {
            // already disabled initializers; proceed regardless
        }

        // drive c through updateLRTConfig with the fuzzed admin and fuzzed target address
        vm.prank(admin);
        bool ok;
        try c.updateLRTConfig(newCfg) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE: for every admissible input, a successful updateLRTConfig(newCfg)
        // MUST leave the stored lrtConfig equal to newCfg.
        // Reference C satisfies this always; the mutant (which drops the assignment)
        // violates it whenever the call succeeds (c.lrtConfig() stays stale).
        assertTrue(!ok || c.lrtConfig() == newCfg);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address newCfg, address caller) public {
        vm.assume(newCfg != address(0));
        // initial config for initialize must be nonzero
        c.initialize(address(1));
        // after initializing, lrtConfig is address(1); to become admin, caller needs DEFAULT_ADMIN_ROLE in config.
        // We cannot change lrtConfig except via updateLRTConfig itself, which requires admin of the CURRENT config.
        // So check the state right after a successful update: c.lrtConfig() must equal newCfg.
        // address(1) has no code, IAccessControl call would fail; use try/catch boundary.
        bool ok;
        vm.prank(caller);
        try c.updateLRTConfig(newCfg) { ok = true; } catch { ok = false; }
        assertTrue(!ok || address(c.lrtConfig()) == newCfg);
    }
}
